import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.WFmvnizL.js";const u=JSON.parse('{"title":"Nezha Monitoring V2 architecture and data flow","description":"Text-based Nezha Monitoring V2 architecture covering Dashboard, Agent, frontends, SQLite, optional TSDB, gRPC connections, service checks, alerts, and remote-operation data flows.","frontmatter":{"title":"Nezha Monitoring V2 architecture and data flow","description":"Text-based Nezha Monitoring V2 architecture covering Dashboard, Agent, frontends, SQLite, optional TSDB, gRPC connections, service checks, alerts, and remote-operation data flows.","outline":"deep"},"headers":[],"relativePath":"en_US/guide/architecture.md","filePath":"en_US/guide/architecture.md","lastUpdated":1785844584000}'),s={name:"en_US/guide/architecture.md"};function i(r,e,d,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="nezha-monitoring-v2-architecture-and-data-flow" tabindex="-1">Nezha Monitoring V2 architecture and data flow <a class="header-anchor" href="#nezha-monitoring-v2-architecture-and-data-flow" aria-label="Permalink to &quot;Nezha Monitoring V2 architecture and data flow&quot;">​</a></h1><p>Nezha Monitoring V2 uses a centralized topology in which one Dashboard manages multiple Agents. Dashboard is the control plane and presentation entry point; Agent is the data-collection and task-execution component on each monitored node. This boundary determines the correct domain, reverse proxy, permission, backup, and troubleshooting design.</p><h2 id="logical-topology" tabindex="-1">Logical topology <a class="header-anchor" href="#logical-topology" aria-label="Permalink to &quot;Logical topology&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser / API client</span></span>
<span class="line"><span>          |</span></span>
<span class="line"><span>          | HTTPS / WebSocket</span></span>
<span class="line"><span>          v</span></span>
<span class="line"><span>+------------------------+        Notification / DNS APIs</span></span>
<span class="line"><span>| Dashboard              |---------------------&gt; External integrations</span></span>
<span class="line"><span>| - User and admin UIs   |</span></span>
<span class="line"><span>| - REST API / MCP       |</span></span>
<span class="line"><span>| - Alert/task scheduler |</span></span>
<span class="line"><span>| - State and access     |</span></span>
<span class="line"><span>+-----------+------------+</span></span>
<span class="line"><span>            |        |</span></span>
<span class="line"><span>            |        +------&gt; SQLite (configuration, users, business data)</span></span>
<span class="line"><span>            |        +------&gt; Optional TSDB (metric and service history)</span></span>
<span class="line"><span>            |</span></span>
<span class="line"><span>            | gRPC (can be carried by an HTTPS reverse proxy)</span></span>
<span class="line"><span>            v</span></span>
<span class="line"><span>     +------+------+------+</span></span>
<span class="line"><span>     | Agent | Agent | ... |</span></span>
<span class="line"><span>     +-------+-------+-----+</span></span>
<span class="line"><span>        |       |</span></span>
<span class="line"><span>        +-------&gt; Host metrics, network checks, authorized tasks</span></span></code></pre></div><p>This is a logical relationship; the components do not need to share one network. Browsers must be able to reach Dashboard, and every Agent must be able to reach the configured Agent endpoint.</p><h2 id="what-does-dashboard-do" tabindex="-1">What does Dashboard do? <a class="header-anchor" href="#what-does-dashboard-do" aria-label="Permalink to &quot;What does Dashboard do?&quot;">​</a></h2><p>Dashboard is responsible for:</p><ul><li>Authenticating users, API Tokens, and Agent connections.</li><li>Receiving host information, runtime state, and task results from Agents.</li><li>Maintaining servers, groups, users, services, notifications, tasks, DDNS, and system configuration.</li><li>Serving data to the user frontend, admin frontend, REST API, and optional MCP endpoint.</li><li>Evaluating service state and alert conditions and invoking configured notification methods.</li><li>Relaying authorized terminal, file, task, NAT, and related operations to the target Agent.</li></ul><p>Dashboard is therefore more than a read-only chart viewer. Once remote operations are enabled, it is a privileged control plane. Restrict the admin surface, use TLS, protect secrets, and keep it updated.</p><h2 id="what-does-agent-do" tabindex="-1">What does Agent do? <a class="header-anchor" href="#what-does-agent-do" aria-label="Permalink to &quot;What does Agent do?&quot;">​</a></h2><p>Agent runs on every monitored device and mainly:</p><ul><li>Reads host and network state exposed by the operating system.</li><li>Connects to Dashboard using a connection secret and its UUID.</li><li>Reports state according to settings such as <code>report_delay</code>.</li><li>Performs assigned HTTP, Ping, or TCP service checks.</li><li>Executes terminal, file, task, update, or NAT operations when they are not disabled and the caller is authorized.</li></ul><p>For nodes that do not need remote operations, use Agent settings such as <code>disable_command_execute</code>, <code>disable_force_update</code>, and <code>disable_nat</code> to reduce its capability. See <a href="/en_US/configuration/agent.html">Agent configuration</a>.</p><h2 id="connections-and-reverse-proxies" tabindex="-1">Connections and reverse proxies <a class="header-anchor" href="#connections-and-reverse-proxies" aria-label="Permalink to &quot;Connections and reverse proxies&quot;">​</a></h2><p>In V2, web access and Agent communication can share the Dashboard listening port, which defaults to <code>8008</code>. Typical deployments use one of two patterns:</p><ol><li><strong>Direct Dashboard port:</strong> browsers and Agents connect to <code>host:8008</code>.</li><li><strong>HTTPS reverse proxy:</strong> the proxy forwards normal HTTP, WebSocket, and gRPC requests to Dashboard.</li></ol><p>The proxy must support both gRPC and WebSocket correctly. Current Agent and Dashboard versions accept both <code>Authorization</code> and <code>Grpc-Metadata-Authorization</code> for gRPC authentication. See <a href="/en_US/guide/q3.html">Dashboard reverse proxy configuration</a> and <a href="/en_US/guide/q4.html">WebSocket troubleshooting</a> for Nginx, Caddy, and CDN details.</p><p>When the public web domain and Agent communication domain differ, configure <code>dashboard_host</code> and <code>install_host</code> separately. These values also participate in OAuth2 callback Host and reserved NAT-domain checks. See <a href="/en_US/configuration/dashboard.html#dashboard-host">Dashboard configuration</a>.</p><h2 id="how-does-state-move-through-the-system" tabindex="-1">How does state move through the system? <a class="header-anchor" href="#how-does-state-move-through-the-system" aria-label="Permalink to &quot;How does state move through the system?&quot;">​</a></h2><h3 id="host-state" tabindex="-1">Host state <a class="header-anchor" href="#host-state" aria-label="Permalink to &quot;Host state&quot;">​</a></h3><p>Agent sends host information and a state stream to Dashboard. Dashboard keeps current state in memory for pages and API queries. When TSDB is enabled, historical server metrics are written to local time-series storage. Real-time state remains available without TSDB, but historical server metrics are unavailable and the frontend locks those history periods.</p><h3 id="service-monitoring" tabindex="-1">Service monitoring <a class="header-anchor" href="#service-monitoring" aria-label="Permalink to &quot;Service monitoring&quot;">​</a></h3><p>Dashboard assigns check tasks to Agents according to the service coverage and selected-server configuration. Each Agent reaches the HTTP, ICMP, or TCP target from its own network location and returns the result. This allows availability and latency comparisons across routes or regions.</p><p>Without TSDB, service history is read from SQLite. After TSDB is enabled, service history is queried from TSDB. See <a href="/en_US/guide/q15.html">Enable TSDB</a> for setup and migration constraints.</p><h3 id="remote-operations" tabindex="-1">Remote operations <a class="header-anchor" href="#remote-operations" aria-label="Permalink to &quot;Remote operations&quot;">​</a></h3><p>When a browser or API client requests terminal, file, or task access, Dashboard first checks user or Token permission, then relays the request through the Agent task or IOStream channel. Terminal, file management, NAT, and MCP file transfer use limited IOStream quotas; close idle sessions when necessary.</p><h2 id="where-is-data-stored" tabindex="-1">Where is data stored? <a class="header-anchor" href="#where-is-data-stored" aria-label="Permalink to &quot;Where is data stored?&quot;">​</a></h2><ul><li><strong>SQLite:</strong> Dashboard uses a local SQLite file for users, configuration, and business data by default.</li><li><strong>Memory:</strong> current online state and runtime objects live in Dashboard memory; after a restart, Agents reconnect and report again.</li><li><strong>Optional TSDB:</strong> setting <code>tsdb.data_path</code> enables built-in time-series storage for server metrics and service history.</li><li><strong>External services:</strong> Dashboard contacts a notification, OAuth2, or DDNS provider only when that integration is configured. The transmitted content depends on the provider template and configuration.</li></ul><p>A backup must include more than the container definition. Script-based installations normally require a backup of <code>/opt/nezha</code>, and Dashboard should be stopped before migration to obtain consistent data. See <a href="/en_US/guide/q5.html">Backup and recovery</a>.</p><h2 id="common-architecture-choices" tabindex="-1">Common architecture choices <a class="header-anchor" href="#common-architecture-choices" aria-label="Permalink to &quot;Common architecture choices&quot;">​</a></h2><h3 id="one-domain-deployment" tabindex="-1">One-domain deployment <a class="header-anchor" href="#one-domain-deployment" aria-label="Permalink to &quot;One-domain deployment&quot;">​</a></h3><p>One HTTPS domain serves browsers and Agents. This is the simplest configuration, but the reverse proxy must handle both WebSocket and gRPC correctly.</p><h3 id="separate-web-and-agent-domains" tabindex="-1">Separate web and Agent domains <a class="header-anchor" href="#separate-web-and-agent-domains" aria-label="Permalink to &quot;Separate web and Agent domains&quot;">​</a></h3><p>The public web domain can use a CDN while the Agent communication domain connects directly or uses a proxy with explicit gRPC support. This avoids some CDN long-connection or gRPC limitations but requires both Host values to be configured correctly.</p><h3 id="private-dashboard" tabindex="-1">Private Dashboard <a class="header-anchor" href="#private-dashboard" aria-label="Permalink to &quot;Private Dashboard&quot;">​</a></h3><p>A VPN, private network, or access-control layer can restrict Dashboard when no public status page is needed. All Agents and administrator clients must still be able to reach the required endpoint.</p><h2 id="pre-production-checklist" tabindex="-1">Pre-production checklist <a class="header-anchor" href="#pre-production-checklist" aria-label="Permalink to &quot;Pre-production checklist&quot;">​</a></h2><ul><li><a href="/en_US/guide/dashboard.html">Install Dashboard</a> and replace the default password.</li><li>Enable HTTPS for public endpoints and configure real-IP headers and trusted Hosts correctly.</li><li>Grant terminal, file, task, NAT, API, and MCP permissions only to users who need them.</li><li>Disable unneeded execution capabilities on Agents.</li><li>Back up SQLite, configuration, and TSDB directories and test restoration.</li><li>Read <a href="/en_US/guide/security.html">Security and privacy</a> and <a href="/en_US/guide/version-compatibility.html">Version and compatibility</a>.</li></ul>`,38)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
